R=[]
R.append(T(3041,"अनानास एंजल केक","अनानास का मनभावन ताज़गी भरा स्वाद हल्के एंजल फ़ूड केक के साथ मिलकर अनानास एंजल केक की इस किडनी-अनुकूल रेसिपी में आता है। केंटकी की DaVita रीनल आहार विशेषज्ञ किम कहती हैं कि उनकी यह आसानी से बनने वाली रेसिपी एक स्वादिष्ट मिठाई या नाश्ता बनाती है।","12","केक का 1/12 हिस्सा",
["1 डिब्बा एंजल फ़ूड केक मिक्स","20 औंस डिब्बाबंद कुचला हुआ अनानास, रस में पैक किया हुआ","8 औंस Cool Whip® फ्रोज़न डेज़र्ट टॉपिंग, पिघली हुई"],
["ओवन को 350° F पर पहले से गरम करें।","सूखे केक मिक्स और बिना निथारे अनानास के पूरे डिब्बे को मिक्सर से अच्छी तरह मिलाएँ और फूला हुआ होने तक फेंटें।","मिश्रण को बिना चिकनाई वाले 9″ x 13″ केक पैन में डालें। ऊपर से हल्का भूरा होने तक 25 से 30 मिनट बेक करें।","पूरी तरह ठंडा होने दें।","बिना डेयरी वाली व्हिप्ड टॉपिंग से फ्रॉस्टिंग करें। फ्रिज में रखें।"],
["अधिक कैलोरी के लिए गाढ़ी चाशनी में पैक किया हुआ अनानास इस्तेमाल करें।"],["1 स्टार्च","1/2 फल, कम पोटैशियम","1 उच्च कैलोरी"]))
R.append(T(3043,"नाशपाती और मसालों के साथ ओवरनाइट ओट्स","करोल के पंपकिन पाई स्पाइस ओट्स विद पियर्स में बहुत कम तैयारी की ज़रूरत होती है। सामग्री को एक जार में मिलाएँ, रात भर फ्रिज में रखें, फिर झटपट नाश्ते के रूप में आनंद लें।","1","1 जार",
["1/2 ताज़ी मध्यम नाशपाती","1/3 कप पारंपरिक ओट्स","2/3 कप बिना मीठा वनीला बादाम दूध","1/2 छोटा चम्मच पंपकिन पाई स्पाइस","1/2 स्कूप व्हे प्रोटीन पाउडर (वैकल्पिक)"],
["नाशपाती के आधे हिस्से को छोटे टुकड़ों में काटें।","सभी सामग्री को मेसन जार में मिलाएँ और अच्छी तरह चलाएँ। रात भर फ्रिज में रखें।","अगले दिन खाने के लिए तैयार। आप अपना नाश्ता सफ़र में ले जा सकते हैं। गरम करना ज़रूरी नहीं है। चाहें तो मीठा करने वाला डालें।"],
["पूरे सप्ताह जल्दी नाश्ते के लिए एक बार में कुछ जार तैयार करें।","यदि आप कुरकुरी बनावट चाहते हैं, तो ताज़ी नाशपाती इस्तेमाल करें और उन्हें सुबह मिलाएँ। ताज़ी नाशपाती की जगह आप कटी हुई नाशपाती का फ्रूट कप (निथारा हुआ) या सेब, बेरी, चेरी या आड़ू जैसे अन्य कम पोटैशियम वाले फल भी इस्तेमाल कर सकते हैं।","ओट्स को रात भर भिगोना “पकाने” का काम करता है। यदि गरम दलिया पसंद है, तो खाने से पहले जार को माइक्रोवेव में 1-2 मिनट गरम करें।"],["1 प्रोटीन (मांस)","1 स्टार्च","1 फल, मध्यम पोटैशियम","1 वसा"]))
R.append(T(3044,"शहद वाला ब्रॉयल्ड ग्रेपफ्रूट","जब आप किडनी आहार पर हों, तो शहद वाले ब्रॉयल्ड ग्रेपफ्रूट की यह रेसिपी अपनी सुबह की शुरुआत करने का एक स्वादिष्ट और सेहतमंद तरीका है।","2","1/2 ग्रेपफ्रूट",
["1 ग्रेपफ्रूट","2 छोटे चम्मच शहद","1/4 छोटा चम्मच दालचीनी"],
["ब्रॉयलर को 400º F पर पहले से गरम करें।","ग्रेपफ्रूट को आधा काटें, फिर हर आधे हिस्से के किनारों और फाँकों के चारों ओर काटें।","हर आधे हिस्से के ऊपर 1 छोटा चम्मच शहद और 1/8 छोटा चम्मच दालचीनी छिड़कें।","ग्रेपफ्रूट को 6 मिनट या भूरा होना शुरू होने तक ब्रॉयल करें।","गरम परोसें।"],
["ब्रॉयल करने से पहले ग्रेपफ्रूट की फाँकें अलग करने से इसे खाना आसान हो जाता है।","ग्रेपफ्रूट और ग्रेपफ्रूट का रस कुछ दवाओं के साथ प्रतिक्रिया करने के लिए जाने जाते हैं। यह सुनिश्चित करने के लिए कि ग्रेपफ्रूट को अपने आहार में शामिल करना सुरक्षित है, अपनी स्वास्थ्य देखभाल टीम से पूछें।"],["1 फल, मध्यम पोटैशियम"]))
R.append(T(3045,"भुनी हुई गरमियों की सब्ज़ियाँ","भुनी हुई सब्ज़ियाँ बाहर से कैरेमलाइज़ हो जाती हैं जबकि अंदर से नरम बनी रहती हैं, और उनका प्राकृतिक स्वाद ऐसा होता है कि अतिरिक्त नमक की ज़रूरत नहीं पड़ती। कम पोटैशियम वाली सब्ज़ियों के सही मेल के लिए टैमी की भुनी हुई गरमियों की सब्ज़ियों की रेसिपी आज़माएँ।","6","3/4 कप",
["2 मध्यम शलगम","1 मध्यम गाजर","लहसुन की 4 कलियाँ","4 छोटे चम्मच ऑलिव ऑयल","1 छोटा चम्मच सूखा मार्जोरम","1 मध्यम प्याज़","1/2 मध्यम लाल शिमला मिर्च","1 छोटी ज़ुकिनी","5 मध्यम सफेद मशरूम","1/4 पाउंड हरी बीन्स","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 375° F पर पहले से गरम करें।","सब्ज़ियों को धोकर सुखा लें। शलगम और गाजर को 2 इंच के टुकड़ों में काटें; लहसुन को बारीक काटें।","शलगम, गाजर और आधा कटा हुआ लहसुन एक कटोरे में रखें और 2 छोटे चम्मच ऑलिव ऑयल छिड़कें। मार्जोरम डालें और सब्ज़ियों पर तेल लगाने के लिए उछालकर मिलाएँ।","दो बेकिंग शीट पर नॉनस्टिक कुकिंग स्प्रे करें; सब्ज़ियों को बाँटकर शीट पर समान रूप से परत में फैलाएँ। बेकिंग शीट को ओवन में 30 मिनट रखें।","जब शलगम और गाजर पक रहे हों, तब प्याज़, लाल शिमला मिर्च और ज़ुकिनी को 2 इंच के टुकड़ों में काटें और मशरूम को आधा काट लें। हरी बीन्स के सिरे हटा दें लेकिन उन्हें साबुत रखें। सब्ज़ियों को एक कटोरे में रखें और 2 छोटे चम्मच ऑलिव ऑयल छिड़कें। बचा हुआ लहसुन और काली मिर्च डालें; सब्ज़ियों पर तेल लग जाने तक धीरे से उछालकर मिलाएँ।","शलगम और गाजर को 30 मिनट पकने के बाद बेकिंग शीट ओवन से निकालें। हरी बीन्स वाले सब्ज़ी मिश्रण को दोनों बेकिंग शीट पर बाँट दें। सब्ज़ियों को आंशिक रूप से पके शलगम और गाजर के साथ मिलाएँ और बेकिंग शीट पर एक परत बनाएँ। 15–20 मिनट के लिए फिर से ओवन में रखें, सब्ज़ियों के नरम होने तक पकाएँ।"],
["भाप में पकी या उबली सब्ज़ियों की तुलना में भुनी हुई सब्ज़ियों में अतिरिक्त स्वाद होता है। नमक की ज़रूरत नहीं है।","सब्ज़ियों के अलग-अलग मेल आज़माएँ।"],["1-1/2 सब्ज़ी, मध्यम पोटैशियम","1/2 वसा"]))
R.append(T(3046,"चटपटी हरी बीन्स","स्वादिष्ट और किडनी-अनुकूल चटपटी हरी बीन्स की रेसिपी का आनंद लें।","6","1/2 कप",
["1 पाउंड जमी हुई फ्रेंच स्टाइल हरी बीन्स","1 बड़ा चम्मच तेल","1/2 कप प्याज़","लहसुन की 1 कली","2 छोटे चम्मच सूखी सोआ की पत्ती (डिल वीड)","1 बड़ा चम्मच नींबू का रस","1 छोटा चम्मच वूस्टरशायर सॉस","1/3 कप सादा ब्रेड क्रम्ब्स","2 बड़े चम्मच बिना नमक का मक्खन"],
["ओवन को 400° F पर पहले से गरम करें।","प्याज़ काटें और लहसुन को बारीक काटें।","हरी बीन्स को पैकेट के निर्देशों के अनुसार माइक्रोवेव में पकाएँ।","एक मध्यम स्किलेट में तेल गरम करें और प्याज़ को लहसुन के साथ तब तक भूनें जब तक प्याज़ पारदर्शी न हो जाए।","सोआ की पत्ती, नींबू का रस और वूस्टरशायर सॉस डालकर मिलाएँ।","हरी बीन्स डालकर उछालकर मिलाएँ। इसे कैसरोल डिश में रखें।","मक्खन पिघलाएँ और ब्रेड क्रम्ब्स के साथ मिलाएँ। इसे हरी बीन्स के मिश्रण पर छिड़कें और भूरा होने के लिए 5 से 10 मिनट बेक करें।"],
[],["1 सब्ज़ी","1 वसा","1/2 स्टार्च"]))
R.append(T(3049,"रेड वाइन विनेग्रेट वाला शतावरी (एस्पैरागस)","अपने अगले सप्ताहांत के रात्रिभोज में रेड वाइन विनेग्रेट वाले शतावरी की इस किडनी-अनुकूल रेसिपी का आनंद लें।","8","1/2 कप",
["लहसुन की 1 कली","2 पाउंड ताज़ा शतावरी (एस्पैरागस)","1 बड़ा चम्मच ऑलिव ऑयल","1/4 कप रेड वाइन विनेग्रेट ड्रेसिंग","1/2 छोटा चम्मच काली मिर्च"],
["लहसुन को बारीक काटें; शतावरी को 2″ के टुकड़ों में काटें।","स्किलेट में तेल गरम करें, लहसुन डालें और 1 मिनट भूनें।","शतावरी के टुकड़े डालें; मिलाने के लिए चलाएँ।","रेड वाइन विनेग्रेट ड्रेसिंग और काली मिर्च डालें।","चलाएँ और 1 मिनट और गरम करें।","आँच से उतारें और परोसें।"],
["रेड वाइन सिरका और ऑलिव ऑयल को बराबर मात्रा में कम सोडियम वाले हर्ब मिश्रण के साथ मिलाकर अपनी खुद की रेड वाइन विनेग्रेट ड्रेसिंग बनाएँ।"],["1 सब्ज़ी, मध्यम पोटैशियम","1/2 वसा"]))
R.append(T(3050,"मिश्रित सब्ज़ियों के साथ लेमोनेड राइस","मिश्रित सब्ज़ियों के साथ लेमोनेड राइस एक स्वादिष्ट और आसानी से बनने वाली किडनी-अनुकूल रेसिपी है।","6","2/3 कप",
["2 बड़े चम्मच प्याज़","12 औंस लेमोनेड (नींबू पानी)","1/2 कप पानी","1 कप ब्राउन राइस, बिना पका","1 कप जमी हुई मिश्रित सब्ज़ियाँ","1/2 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच पिसा जायफल","1/8 छोटा चम्मच नमक"],
["प्याज़ को बारीक काटें।","लेमोनेड और पानी को राइस कुकर या सॉसपैन में डालें। चावल, प्याज़, मिश्रित सब्ज़ियाँ और मसाले डालें।","राइस कुकर चालू करें या स्टोव पर ढककर मध्यम आँच पर 20 मिनट पकाएँ।"],
["इस रेसिपी में ताज़ा, जमा हुआ, बोतलबंद या डिब्बाबंद लेमोनेड इस्तेमाल किया जा सकता है। ध्यान रखें, कुछ लेमोनेड में फॉस्फेट मिलावट वाले योजक होते हैं जिनसे फॉस्फोरस की मात्रा बढ़ती है। लेबल पढ़ें और इस योजक वाले ब्रांड से बचें।","गाजर, मक्का, हरी बीन्स, हरी मटर वाला सब्ज़ी मिश्रण चुनें या अपनी पसंदीदा कम पोटैशियम वाली जमी हुई सब्ज़ियों का मिश्रण इस्तेमाल करें।","यदि आपको मधुमेह है, तो प्रति सर्विंग कार्बोहाइड्रेट को 5 ग्राम घटाने के लिए इस रेसिपी में बिना चीनी वाला लेमोनेड आज़माएँ।","सबसे अच्छे नतीजों के लिए पकाते समय ढक्कन न हटाएँ और चावल को न चलाएँ।"],["1-1/2 स्टार्च","1 सब्ज़ी, कम पोटैशियम"]))
R.append(T(3051,"मिश्रित सब्ज़ी सलाद","लाल मिर्च, नींबू का रस और खीरा किडनी-अनुकूल रेसिपी, मिश्रित सब्ज़ी सलाद, को बनाने वाली कुछ स्वादिष्ट सामग्रियाँ हैं।","4","1/2 कप",
["1 मध्यम खीरा","1 मीठी लाल शिमला मिर्च","1/2 गुच्छा ताज़ी सोआ (डिल)","3 हरे प्याज़ (स्कैलियन)","1 बड़ा चम्मच नींबू का रस","1/3 कप खट्टी क्रीम (सावर क्रीम)","1/8 छोटा चम्मच काली मिर्च"],
["खीरे और लाल शिमला मिर्च को छीलकर, बीज निकालकर छोटे टुकड़ों में काटें।","सोआ और हरे प्याज़ को काट लें।","सभी सामग्री को परोसने के कटोरे में मिलाएँ।","परोसने से पहले कम से कम एक घंटे ठंडा करें।"],
["यदि चाहें तो कम वसा वाली खट्टी क्रीम इस्तेमाल करें।"],["1 सब्ज़ी, मध्यम पोटैशियम","1/2 वसा"]))
R.append(T(3052,"ग्रैंड चैंपियन एप्पल पाई","ग्रैंड चैंपियन एप्पल पाई नॉर्थ कैरोलिना की रीनल आहार विशेषज्ञ बार्ब ने भेजी थी। इस किडनी-अनुकूल डीप-डिश व्यंजन को बेक करें और इसकी मनभावन खुशबू के साथ-साथ लुभावने स्वाद का भी आनंद लें।","8","पाई का 1/8 हिस्सा",
["4 बड़े अंडे","1-1/2 कप सेब की प्यूरी (एप्पलसॉस)","3/4 कप दबाकर भरी हुई ब्राउन शुगर","3 बड़े चम्मच मैदा","1 छोटा चम्मच कद्दूकस किया हुआ नींबू का छिलका","4 बड़े चम्मच नींबू का रस","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच पिसा जायफल","1 बिना बेक किया हुआ डीप-डिश पाई शेल, 9” आकार का","1 मध्यम सेब","1/4 कप खुबानी का जैम"],
["ओवन को 450° F पर पहले से गरम करें।","एक बड़े मिक्सिंग बाउल में अंडे, सेब की प्यूरी, ब्राउन शुगर, मैदा, नींबू का छिलका, 3 बड़े चम्मच नींबू का रस, नमक, दालचीनी और जायफल मिलाएँ; अच्छी तरह मिलाएँ।","मिश्रण को बिना बेक किए पाई शेल में डालें। 15 मिनट बेक करें। ओवन का तापमान घटाकर 300° F कर दें। 45 मिनट और बेक करें या जब तक बीच के पास डाला गया चाकू साफ न निकले। जाली पर थोड़ा ठंडा होने दें।","पाई के बेक होने के दौरान सेब को छीलकर पतले स्लाइस में काटें।","सेब के स्लाइस और 1 बड़ा चम्मच नींबू का रस एक कटोरे में अच्छी तरह मिलाएँ। सेब के स्लाइस को पिनव्हील के आकार में बेक की हुई पाई के ऊपर सजाएँ।","जैम को छोटे सॉसपैन में धीमी आँच पर लगातार चलाते हुए पिघलाएँ। सेब के स्लाइस पर पिघला हुआ जैम ब्रश से लगाएँ।","पाई को ब्रॉयलर पैन की जाली पर रखें। ताप स्रोत से 6” दूर 3 मिनट या सेब के नरम होने और जैम में बुलबुले उठने तक ब्रॉयल करें।"],
["मधुमेह रोगियों के लिए कम कार्बोहाइड्रेट वाले विकल्पों में ब्राउन शुगर की जगह 1/4 कप + 2 बड़े चम्मच Splenda® Brown Sugar Blend का उपयोग और जैम की जगह खुबानी का फ्रूट स्प्रेड इस्तेमाल करना शामिल है। इससे कैलोरी घटकर 216, कार्बोहाइड्रेट 32 ग्राम और 2 कार्बोहाइड्रेट विकल्प हो जाते हैं।","तैयार पाई क्रस्ट में सोडियम की मात्रा ब्रांड के अनुसार अलग-अलग होती है। सबसे कम सोडियम वाला ब्रांड चुनें या कम नमक के साथ घर पर पाई क्रस्ट बनाने पर विचार करें।"],["1 स्टार्च","1 फल, कम पोटैशियम","1 उच्च कैलोरी","1-1/2 वसा"]))
R.append(T(3053,"मलाईदार विनेग्रेट ड्रेसिंग के साथ चावल और मिर्च का सलाद","इस किडनी-अनुकूल रेसिपी, मलाईदार विनेग्रेट ड्रेसिंग के साथ चावल और मिर्च का सलाद, से रसोई की मेज़ पर थोड़ा मसालेदार स्वाद जोड़ें।","8","1/2 कप",
["1 कप लंबे दाने वाला सफेद चावल, बिना पका","1/4 छोटा चम्मच नमक","1 बड़ी पोब्लानो मिर्च","1 कप जमी हुई मटर","1 कप खीरा","1/4 कप हरे प्याज़","1/4 कप ताज़ा हरा धनिया","1/2 कप लाल शिमला मिर्च","1/2 कप हरी शिमला मिर्च","लहसुन की 1 कली","2 बड़े चम्मच सेब का सिरका","2 बड़े चम्मच ताज़ा नींबू (लाइम) का रस","1 छोटा चम्मच डिजॉन सरसों","1 छोटा चम्मच पिसा जीरा","1/2 कप खट्टी क्रीम (सावर क्रीम)","2 बड़े चम्मच ऑलिव ऑयल","1/4 छोटा चम्मच काली मिर्च"],
["चावल पकाने के लिए 2 क्वार्ट के सॉसपैन में 1-3/4 कप पानी उबालें और चावल व नमक डालें। पानी में दोबारा उबाल आने दें, एक बार चलाएँ, ढक दें और आँच धीमी करके 15 मिनट या पानी सूखने तक पकाएँ। आँच से उतारें और ढककर कम से कम 10 मिनट रखें।","मिर्च को भूनने के लिए उसे ब्रॉयलर के नीचे रखें और समान रूप से जलने तक बार-बार पलटें। जब मिर्च चारों तरफ से काली पड़ जाए, तो उसे प्लास्टिक बैग या कटोरे में डालें, ढककर सील करें और ठंडा होने दें। मिर्च से जली हुई त्वचा हटाएँ, धोएँ और थपथपाकर सुखा लें। मिर्च को छोटे टुकड़ों में काटें।","मटर को पिघलने दें; खीरे को छीलकर बीज निकालें; खीरा, हरे प्याज़ और हरा धनिया काटें; शिमला मिर्च को छोटे टुकड़ों में काटें और लहसुन को बारीक काटें।","सलाद तैयार करने के लिए चावल और कटी मिर्च मिलाएँ। पिघली हुई मटर, शिमला मिर्च, प्याज़, खीरा और हरा धनिया डालें। अच्छी तरह उछालकर मिलाएँ।","ड्रेसिंग तैयार करने के लिए ड्रेसिंग की सभी सामग्री मिलाएँ और अच्छी तरह मिलाएँ।","ड्रेसिंग को चावल और सब्ज़ियों के मिश्रण में उछालकर मिलाएँ। परोसने तक ठंडा करें।"],
["पोब्लानो मिर्च को एंको मिर्च भी कहा जाता है।","मिर्च को पहले से भूनें ताकि उन्हें ठंडा होने का समय मिले।","तीखी मिर्च से बीज और नस निकालते समय रबर के दस्ताने पहनें।","अच्छी प्रस्तुति के लिए इसे सलाद के पत्तों से सजी थाली में परोसें।"],["1 सब्ज़ी, मध्यम पोटैशियम","1 स्टार्च","1 वसा"]))
R.append(T(3054,"टर्की भरी हरी शिमला मिर्च","अपने अगले रात्रिभोज में टर्की भरी हरी शिमला मिर्च की इस किडनी-अनुकूल रेसिपी को आज़माएँ।","8","1 शिमला मिर्च",
["8 बड़ी हरी शिमला मिर्च","2 पाउंड कीमा टर्की","1 कप पका हुआ ब्राउन राइस","1 बड़ा चम्मच मीठी हंगेरियन पेपरिका","1/2 छोटा चम्मच नमक","1 अंडा","1 मध्यम प्याज़, बारीक कटा हुआ","3 मध्यम लहसुन की कलियाँ, बारीक कटी हुई","1/2 कप कुचले हुए टमाटर","1 कप कम सोडियम वाला बीफ़ शोरबा"],
["ओवन को 350°F पर पहले से गरम करें।","शिमला मिर्च के डंठल हटाएँ और अंदर से बीज और झिल्लियाँ साफ करें।","टर्की, चावल, अंडा, प्याज़, लहसुन और मसालों को अच्छी तरह मिलाएँ।","शिमला मिर्च में मांस का मिश्रण भरें।","शिमला मिर्च को एक बड़े रोस्टर में रखें।","शिमला मिर्च के ऊपर कुचले हुए टमाटर और शोरबा डालें।","1 घंटा 15 मिनट बेक करें।"],
["सबसे कम चर्बी वाली भरावन के लिए कीमा टर्की ब्रेस्ट का उपयोग करें, लेकिन कम चर्बी वाला कीमा बीफ़ भी हृदय के लिए लाभकारी भरावन है।","यदि आप पोटैशियम-प्रतिबंधित आहार पर नहीं हैं, तो कुचले हुए टमाटर का 16 औंस का डिब्बा इस्तेमाल करें।","दोगुनी मात्रा बनाएँ और अलग-अलग शिमला मिर्च को फ्रीज़ करें ताकि जब खाना बनाने का मन न हो तब आसानी से भोजन तैयार हो जाए।","भरी हुई शिमला मिर्च पूरे मध्य और पूर्वी यूरोप में आम है। मसाले और किस मांस से भरा जाए, यह न केवल एक क्षेत्र से दूसरे क्षेत्र में, बल्कि एक ही क्षेत्र के भीतर भी अलग-अलग होता है। कुछ लोग 100% कीमा बीफ़ इस्तेमाल करते हैं, तो कुछ मांस का मिश्रण।","कम प्रोटीन वाले आहार के लिए आप एक पाउंड टर्की इस्तेमाल कर सकते हैं और चावल बढ़ाकर 3 कप कर सकते हैं।"],["3 मांस","2 सब्ज़ियाँ, उच्च पोटैशियम"]))
R.append(T(3056,"तरबूज़ एगुआ फ्रेस्का","ताज़ा पानी में तरबूज़ और नींबू (लाइम) का रस मिलाकर बनाया गया यह पेय गरमी के दिन या किसी भी समय प्यास बुझाने के लिए एकदम सही है। तरबूज़ एगुआ फ्रेस्का में पोटैशियम कम होता है, जिससे यह किडनी आहार के लिए बढ़िया विकल्प है।","4","1 कप",
["2 कप तरबूज़, बिना बीज वाला","1/4 कप पानी","1/4 कप चीनी","पुदीने की पत्तियों की 2 टहनियाँ","1 नींबू (लाइम) (सजावट के लिए)"],
["नींबू को स्लाइस में काटें। तरबूज़ को बड़े टुकड़ों में काटें और 2 कप नाप लें।","तरबूज़ को 2 नींबू स्लाइस के साथ ब्लेंडर में डालें और चिकना होने तक ब्लेंड करें।","मिश्रण को छलनी से छानें और 4 कपों में डालें। पुदीने की पत्तियों और नींबू के स्लाइस से सजाएँ और परोसें।"],
["कार्बोहाइड्रेट को 12 ग्राम तक घटाने के लिए चीनी की जगह स्टीविया स्वीटनर का उपयोग करें।"],["1 फल, मध्यम पोटैशियम","1 उच्च कैलोरी"]))
R.append(T(3061,"अनानास नॉन-डेयरी “आइसक्रीम” ट्रीट्स","सिर्फ़ चार सामग्री और बिना पकाए, अनानास नॉन-डेयरी “आइसक्रीम” ट्रीट्स बजट के अनुकूल और बनाने में आसान हैं।","18","1 ट्रीट; 2-1/4” का वर्ग",
["20 औंस का डिब्बाबंद कुचला हुआ अनानास, अच्छी तरह निथारा हुआ","4 स्कूप वनीला व्हे प्रोटीन पाउडर","16 औंस का लाइट व्हिप्ड टॉपिंग कंटेनर","36 ग्राहम क्रैकर वर्ग"],
["निथारे हुए अनानास और प्रोटीन पाउडर को अच्छी तरह मिलाएँ, फिर व्हिप्ड टॉपिंग को धीरे से मिलाएँ।","ग्राहम क्रैकर वर्गों की एक परत कुकी शीट पर रखें और हर क्रैकर पर लगभग 2 बड़े चम्मच टॉपिंग का मिश्रण फैलाएँ।","ऊपर एक और ग्राहम क्रैकर वर्ग रखें और कुकी शीट को फ्रीज़र में रखें।","जब अच्छी तरह जम जाए, तो हर एक को अलग-अलग प्लास्टिक रैप में लपेटें और फ्रीज़र में वायुरोधी डिब्बे में रखें।"],
["कुछ व्हिप्ड टॉपिंग में फॉस्फोरस वाले योजक होते हैं। सामग्री की सूची देखें ताकि सुनिश्चित हो कि फॉस्फोरस मिलाया नहीं गया है।","14.4 औंस के ग्राहम क्रैकर के डिब्बे में लगभग 27 आयताकार शीट होती हैं।","प्रोटीन पाउडर में प्रोटीन, पोटैशियम, फॉस्फोरस और सोडियम की मात्रा अलग-अलग हो सकती है। आप अपने आहार विशेषज्ञ से बात कर सकते हैं कि आपके लिए कौन सा उपयुक्त होगा।"],["1-1/2 स्टार्च"]))
R.append(T(3063,"भुनी हुई हरी बीन्स (ग्रीन बीन्स अ ला रोस्ट)","ऐसी सब्ज़ियाँ आपने पहले कभी नहीं चखी होंगी! ओहायो के DaVita रीनल आहार विशेषज्ञ ब्रैडी हमें दिखाते हैं कि हरी बीन्स को कैसे भूना जाए ताकि वे नरम और लुभावनी बनें! इस व्यंजन के साथ आपको अपने बच्चों से सब्ज़ियाँ खिलवाने की चिंता नहीं करनी पड़ेगी। और यह किडनी-अनुकूल आहार में भी फिट बैठता है, इसलिए आप निश्चिंत रह सकते हैं कि हर कोई भुनी हुई हरी बीन्स की दूसरी सर्विंग माँगेगा!","4","1 कप",
["1 पाउंड ताज़ी हरी बीन्स","1-1/2 बड़े चम्मच ऑलिव ऑयल","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 450° F पर पहले से गरम करें।","हरी बीन्स को धोकर उनके सिरे काट दें।","किनारे वाली बेकिंग शीट पर एल्युमीनियम फॉइल बिछाएँ और उस पर बीन्स फैलाएँ।","बीन्स पर ऑलिव ऑयल डालें और बीन्स पर समान रूप से तेल लगाने के लिए धीरे से उछालें।","ओवन में 10 मिनट भूनें।","बेकिंग शीट को ओवन से निकालें और समान रूप से पकने के लिए बीन्स को दोबारा फैलाएँ।","वापस ओवन में रखें और लगभग 10 मिनट और बेक करें या जब तक बीन्स में कुछ जगह सुनहरे भूरे धब्बे न आ जाएँ।","ओवन से निकालें, पिसी काली मिर्च डालें और परोसें।"],
["अतिरिक्त स्वाद के लिए नींबू या हर्ब के स्वाद वाला फ्लेवर्ड तेल आज़माएँ।"],["1 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]))
R.append(T(3065,"नारियल की ब्रेड","कद्दूकस किया हुआ नारियल और खट्टी क्रीम किडनी-अनुकूल नारियल की ब्रेड को मिठास और नमी का सही संतुलन देते हैं। इसे हवाईयन ट्रीट में बदलने के लिए थोड़ा अनानास मिलाएँ।","12","1 स्लाइस",
["2 बड़े चम्मच नारियल का तेल","1/3 कप बिना नमक का मक्खन","1/2 कप चीनी","2 बड़े अंडे","1 कप मीठा, सूखा, कद्दूकस किया हुआ नारियल","1 कप खट्टी क्रीम (सावर क्रीम)","2 कप मैदा","1 छोटा चम्मच बेकिंग सोडा","1-1/2 छोटा चम्मच बेकिंग पाउडर"],
["ओवन को 350° F पर पहले से गरम करें। 9 x 5 इंच के लोफ पैन में चिकनाई लगाएँ। मक्खन को नरम होने के लिए बाहर रखें।","नारियल के तेल को माइक्रोवेव में बस पिघलने तक गरम करें। ठंडा होने के लिए एक तरफ रखें।","मक्खन और चीनी को एक साथ क्रीमी होने तक फेंटें। नारियल का तेल और अंडे डालें; एक साथ मिलाएँ। खट्टी क्रीम मिलाएँ। मिश्रण में कद्दूकस किया हुआ नारियल डालें और चलाएँ।","एक अलग कटोरे में मैदा, बेकिंग सोडा और बेकिंग पाउडर मिलाएँ।","सूखी सामग्री को गीली सामग्री में धीरे से मिलाएँ। घोल को लोफ पैन में डालें।","45 से 60 मिनट बेक करें, जब तक ब्रेड सुनहरी भूरी न हो जाए और टूथपिक साफ न निकले।","ब्रेड को पैन में 5 से 10 मिनट ठंडा करें, फिर पैन से निकालकर जाली पर ठंडा करें।"],
["यदि चाहें तो 1/2 कप कटा हुआ या कुचला हुआ अनानास मिलाएँ।","ब्रेड के कुछ स्लाइस को फ्रीज़र रैप में लपेटें और बाद में झटपट नाश्ते के लिए फ्रीज़ करें।"],["1 स्टार्च","1/2 उच्च कैलोरी","1-1/2 वसा"]))
save(4,R)
